const form=document.querySelector('#form'),input=document.querySelector('#text'),status=document.querySelector('#status'),list=document.querySelector('#list'),create=document.querySelector('#create'),reload=document.querySelector('#reload');
async function call(method,body){const response=await fetch('/api/notes',{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(!response.ok){const message=await response.text();throw Error(response.status===409?'O limite de 20 anotações foi atingido.':response.status===400?'Confira o texto: a anotação deve caber em 2 KiB de JSON.':message||'Não foi possível concluir. Inicie o backend e tente novamente.');}return response.json();}
async function load(){const data=await call('GET');list.replaceChildren();for(const item of data.items){const li=document.createElement('li'),text=document.createElement('span'),date=document.createElement('small');text.textContent=item.value.text;date.textContent=new Date(item.created_at).toLocaleString('pt-BR');li.append(text,date);list.append(li);}return data.items.length;}
async function busy(action){create.disabled=reload.disabled=true;try{await action();}catch(error){status.textContent=error.message;}finally{create.disabled=reload.disabled=false;}}
form.addEventListener('submit',event=>{event.preventDefault();busy(async()=>{await call('POST',{text:input.value});input.value='';status.textContent='Anotação salva.';try{await load();}catch{status.textContent='Anotação salva. Atualize a lista para recuperá-la.';}});});
reload.addEventListener('click',()=>busy(async()=>{const count=await load();status.textContent=count?`${count} anotação(ões) recuperada(s).`:'Sua lista ainda está vazia.';}));
